def find_Min_Sum(num): 
    sum = 0
    i = 2
    while(i * i <= num): 
        while(num % i == 0): 
            sum += i 
            num /= i 
        i += 1
    sum += num 
    return sum

def find_Min_Sum(arg1):
    """Write a python function to find minimum sum of factors of a given number."""
    # Initialize the minimum sum to a large number
    min_sum = float('inf')

    # Iterate through possible divisors from 1 to the square root of arg1
    for i in range(1, int(arg1**0.5) + 1):
        if arg1 % i == 0:
            # Calculate the sum of factors
            factor_sum = i + arg1 // i
            # Update the minimum sum if the current sum is smaller
            if factor_sum < min_sum:
                min_sum = factor_sum

    return min_sum

