def lbs(arr): 
	n = len(arr) 
	lis = [1 for i in range(n+1)] 
	for i in range(1 , n): 
		for j in range(0 , i): 
			if ((arr[i] > arr[j]) and (lis[i] < lis[j] +1)): 
				lis[i] = lis[j] + 1
	lds = [1 for i in range(n+1)] 
	for i in reversed(range(n-1)): 
		for j in reversed(range(i-1 ,n)): 
			if(arr[i] > arr[j] and lds[i] < lds[j] + 1): 
				lds[i] = lds[j] + 1
	maximum = lis[0] + lds[0] - 1
	for i in range(1 , n): 
		maximum = max((lis[i] + lds[i]-1), maximum) 
	return maximum

def lbs(arr):
    # Initialize a list to store the length of the longest increasing subsequence ending at each index
    lis = [1] * len(arr)

    # Iterate through the array starting from the second element
    for i in range(1, len(arr)):
        # Compare each element with its previous one
        for j in range(i):
            # If the current element is greater than the previous one and the length of the increasing subsequence ending at j is less than the current length of the increasing subsequence ending at i
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # The maximum value in the lis list will be the length of the longest increasing subsequence
    return max(lis)

