def lbs(arr):
    # Initialize the maximum length of the longest bitonic subsequence
    max_length = 1

    # Iterate through the array starting from the second element
    for i in range(1, len(arr)):
        # If the current element is greater than the previous one, update the maximum length
        if arr[i] > arr[i - 1]:
            max_length = max(max_length, 2)

        # If the current element is less than the previous one, update the maximum length
        elif arr[i] < arr[i - 1]:
            # Check if the previous element is greater than the current element
            if arr[i - 1] > arr[i]:
                # Update the maximum length to the maximum of itself and 2
                max_length = max(max_length, 2 + arr[i - 1])

    return max_length

